<template>
  <div class="q-pa-lg">
    <div class="text-h4 q-mb-lg">
      <q-icon name="bug_report" class="q-mr-sm" />
      WebSocket Debug Console
    </div>

    <div class="row q-gutter-lg">
      <!-- Diagnostic Panel -->
      <div class="col-md-6 col-sm-12">
        <WebSocketDiagnostics />
      </div>

      <!-- Live Testing Panel -->
      <div class="col-md-6 col-sm-12">
        <q-card>
          <q-card-section>
            <div class="text-h6 q-mb-md">
              <q-icon name="play_circle" class="q-mr-sm" />
              Live Testing
            </div>

            <!-- WebSocket URL Testing -->
            <div class="q-mb-lg">
              <div class="text-subtitle2 q-mb-sm">WebSocket Endpoint</div>
              <q-input
                v-model="websocketUrl"
                readonly
                outlined
                dense
                label="Current WebSocket URL"
              />
              <q-btn
                class="q-mt-sm"
                color="primary"
                icon="link"
                label="Test Endpoint Accessibility"
                @click="testEndpoint"
                :loading="testingEndpoint"
              />
            </div>

            <!-- Manual Dashboard Request -->
            <div class="q-mb-lg">
              <div class="text-subtitle2 q-mb-sm">Dashboard Data Request</div>
              <q-input
                v-model="dashboardFilters"
                outlined
                dense
                label="Filter Parameters (JSON)"
                type="textarea"
                rows="3"
              />
              <q-btn
                class="q-mt-sm"
                color="secondary"
                icon="dashboard"
                label="Request Dashboard Data"
                @click="requestDashboardData"
                :loading="requestingData"
              />
            </div>

            <!-- Channel Subscription Testing -->
            <div class="q-mb-lg">
              <div class="text-subtitle2 q-mb-sm">Channel Subscription</div>
              <q-input
                v-model="channelName"
                outlined
                dense
                label="Channel Name"
                placeholder="dashboard"
              />
              <div class="q-gutter-sm q-mt-sm">
                <q-btn
                  color="positive"
                  icon="add_circle"
                  label="Subscribe"
                  @click="subscribeToChannel"
                  size="sm"
                />
                <q-btn
                  color="negative"
                  icon="remove_circle"
                  label="Unsubscribe"
                  @click="unsubscribeFromChannel"
                  size="sm"
                />
              </div>
            </div>

            <!-- Results Display -->
            <div class="q-mb-lg">
              <div class="text-subtitle2 q-mb-sm">Last Response</div>
              <q-scroll-area style="height: 200px">
                <pre class="response-display">{{ lastResponse }}</pre>
              </q-scroll-area>
            </div>
          </q-card-section>
        </q-card>
      </div>
    </div>

    <!-- Quick Actions -->
    <div class="fixed-bottom-right q-ma-lg">
      <q-btn fab color="primary" icon="home" @click="goToDashboard">
        <q-tooltip>Back to Dashboard</q-tooltip>
      </q-btn>
    </div>
  </div>
</template>

<script>
import { defineComponent, ref, computed, onMounted } from 'vue';
import { useWebSocketStore } from 'src/store/main';
import { storeToRefs } from 'pinia';
import { WEB_SOCKET_URL } from 'src/pages/APIs';
import { useRouter } from 'vue-router';
import WebSocketDiagnostics from 'src/components/diagnostics/WebSocketDiagnostics.vue';

export default defineComponent({
  name: 'DebugWebSocket',

  components: {
    WebSocketDiagnostics,
  },

  setup() {
    const router = useRouter();
    const websocketStore = useWebSocketStore();
    const { isConnected, dashboard_data } = storeToRefs(websocketStore);

    const testingEndpoint = ref(false);
    const requestingData = ref(false);
    const channelName = ref('dashboard');
    const dashboardFilters = ref('{}');
    const lastResponse = ref('No response yet...');

    const websocketUrl = computed(() => {
      const protocol = WEB_SOCKET_URL.startsWith('https') ? 'wss' : 'ws';
      const url = WEB_SOCKET_URL.replace(/^https?:\/\//, '');
      return `${protocol}://${url}/ws/v2`;
    });

    async function testEndpoint() {
      testingEndpoint.value = true;
      lastResponse.value = 'Testing endpoint accessibility...';

      try {
        // Test basic connectivity
        const response = await fetch(
          WEB_SOCKET_URL.replace('/ws/v2', '/health'),
          {
            method: 'GET',
            timeout: 5000,
          },
        );

        lastResponse.value = JSON.stringify(
          {
            status: response.status,
            statusText: response.statusText,
            headers: Object.fromEntries(response.headers.entries()),
            timestamp: new Date().toISOString(),
          },
          null,
          2,
        );
      } catch (error) {
        lastResponse.value = JSON.stringify(
          {
            error: error.message,
            websocketUrl: websocketUrl.value,
            baseUrl: WEB_SOCKET_URL,
            timestamp: new Date().toISOString(),
          },
          null,
          2,
        );
      } finally {
        testingEndpoint.value = false;
      }
    }

    async function requestDashboardData() {
      requestingData.value = true;
      lastResponse.value = 'Requesting dashboard data...';

      try {
        let filters = {};
        try {
          filters = JSON.parse(dashboardFilters.value);
        } catch (e) {
          filters = {};
        }

        const result = await websocketStore.sendMessageByType(
          'dashboard',
          filters,
        );
        lastResponse.value = JSON.stringify(
          {
            success: true,
            data: result,
            documentsCount: result?.documents?.length || 0,
            timestamp: new Date().toISOString(),
          },
          null,
          2,
        );
      } catch (error) {
        lastResponse.value = JSON.stringify(
          {
            error: error.message,
            isConnected: isConnected.value,
            filters: dashboardFilters.value,
            timestamp: new Date().toISOString(),
          },
          null,
          2,
        );
      } finally {
        requestingData.value = false;
      }
    }

    function subscribeToChannel() {
      try {
        websocketStore.subscribeToChannel(channelName.value);
        lastResponse.value = `Subscribed to channel: ${channelName.value}`;
      } catch (error) {
        lastResponse.value = `Subscription failed: ${error.message}`;
      }
    }

    function unsubscribeFromChannel() {
      try {
        websocketStore.unsubscribeToChannel(channelName.value);
        lastResponse.value = `Unsubscribed from channel: ${channelName.value}`;
      } catch (error) {
        lastResponse.value = `Unsubscription failed: ${error.message}`;
      }
    }

    function goToDashboard() {
      router.push('/dashboard');
    }

    onMounted(() => {
      console.log('🐛 [Debug] WebSocket debug console initialized');
      lastResponse.value = JSON.stringify(
        {
          message: 'WebSocket debug console ready',
          currentUrl: websocketUrl.value,
          isConnected: isConnected.value,
          timestamp: new Date().toISOString(),
        },
        null,
        2,
      );
    });

    return {
      websocketUrl,
      testingEndpoint,
      requestingData,
      channelName,
      dashboardFilters,
      lastResponse,
      testEndpoint,
      requestDashboardData,
      subscribeToChannel,
      unsubscribeFromChannel,
      goToDashboard,
    };
  },
});
</script>

<style scoped>
.response-display {
  background: #f5f5f5;
  padding: 12px;
  border-radius: 4px;
  font-size: 12px;
  white-space: pre-wrap;
  word-break: break-word;
}

.fixed-bottom-right {
  position: fixed;
  bottom: 0;
  right: 0;
  z-index: 999;
}
</style>
