<template>
  <q-card class="websocket-diagnostics">
    <q-card-section>
      <div class="text-h6 q-mb-md">
        <q-icon name="wifi" class="q-mr-sm" />
        WebSocket Diagnostics
      </div>

      <!-- Connection Status -->
      <div class="diagnostic-section">
        <div class="section-title">Connection Status</div>
        <q-list>
          <q-item>
            <q-item-section avatar>
              <q-icon
                :name="connectionStatus.icon"
                :color="connectionStatus.color"
              />
            </q-item-section>
            <q-item-section>
              <q-item-label>{{ connectionStatus.text }}</q-item-label>
              <q-item-label caption>{{ connectionStatus.url }}</q-item-label>
            </q-item-section>
          </q-item>

          <q-item>
            <q-item-section avatar>
              <q-icon name="token" color="blue" />
            </q-item-section>
            <q-item-section>
              <q-item-label>Authentication: {{ authStatus }}</q-item-label>
              <q-item-label caption
                >Token length: {{ tokenLength }}</q-item-label
              >
            </q-item-section>
          </q-item>
        </q-list>
      </div>

      <!-- Dashboard Data Status -->
      <div class="diagnostic-section">
        <div class="section-title">Dashboard Data Flow</div>
        <q-list>
          <q-item>
            <q-item-section avatar>
              <q-icon name="dashboard" color="primary" />
            </q-item-section>
            <q-item-section>
              <q-item-label>Data Source: {{ dataSource }}</q-item-label>
              <q-item-label caption
                >Last updated: {{ lastDataUpdate }}</q-item-label
              >
            </q-item-section>
          </q-item>

          <q-item>
            <q-item-section avatar>
              <q-icon name="description" color="info" />
            </q-item-section>
            <q-item-section>
              <q-item-label>Documents: {{ documentsCount }}</q-item-label>
              <q-item-label caption
                >Data flag: {{ dashboard_data_flag }}</q-item-label
              >
            </q-item-section>
          </q-item>
        </q-list>
      </div>

      <!-- Manual Actions -->
      <div class="diagnostic-section">
        <div class="section-title">Manual Testing</div>
        <div class="q-gutter-md">
          <q-btn
            color="primary"
            icon="refresh"
            label="Test WebSocket Connection"
            @click="testWebSocketConnection"
            :loading="testing"
          />

          <q-btn
            color="secondary"
            icon="download"
            label="Request Dashboard Data"
            @click="requestDashboardData"
            :loading="requesting"
          />

          <q-btn
            color="info"
            icon="info"
            label="Export Diagnostics"
            @click="exportDiagnostics"
          />
        </div>
      </div>

      <!-- Real-time Logs -->
      <div class="diagnostic-section">
        <div class="section-title">Real-time Logs (Last 10)</div>
        <q-scroll-area style="height: 200px" class="log-container">
          <div
            v-for="(log, index) in recentLogs"
            :key="index"
            class="log-entry"
          >
            <span :class="'log-' + log.level">{{ log.timestamp }}</span>
            <span class="log-message">{{ log.message }}</span>
          </div>
        </q-scroll-area>

        <q-btn
          flat
          size="sm"
          icon="clear"
          label="Clear Logs"
          @click="clearLogs"
          class="q-mt-sm"
        />
      </div>
    </q-card-section>
  </q-card>
</template>

<script>
import { defineComponent, ref, computed, onMounted, onUnmounted } from 'vue';
import { useWebSocketStore } from 'src/store/main';
import { storeToRefs } from 'pinia';

export default defineComponent({
  name: 'WebSocketDiagnostics',

  setup() {
    const websocketStore = useWebSocketStore();
    const { isConnected, hasError, dashboard_data, dashboard_data_flag } =
      storeToRefs(websocketStore);

    const testing = ref(false);
    const requesting = ref(false);
    const recentLogs = ref([]);
    const lastDataUpdate = ref('Never');

    // Computed properties for status display
    const connectionStatus = computed(() => {
      if (isConnected.value) {
        return {
          icon: 'wifi',
          color: 'positive',
          text: 'Connected',
          url: websocketStore.socket?.url || 'Unknown',
        };
      } else if (hasError.value) {
        return {
          icon: 'wifi_off',
          color: 'negative',
          text: 'Error',
          url: 'Connection failed',
        };
      } else {
        return {
          icon: 'wifi_tethering',
          color: 'warning',
          text: 'Connecting...',
          url: 'Establishing connection',
        };
      }
    });

    const authStatus = computed(() => {
      return isConnected.value ? 'Authenticated' : 'Not authenticated';
    });

    const tokenLength = computed(() => {
      try {
        // This is just for diagnostic display
        return 'Available';
      } catch {
        return 'Not available';
      }
    });

    const dataSource = computed(() => {
      return dashboard_data_flag.value ? 'WebSocket' : 'HTTPS API';
    });

    const documentsCount = computed(() => {
      return dashboard_data.value?.documents?.length || 0;
    });

    // Log capture functions
    const originalLog = console.log;
    const originalError = console.error;
    const originalWarn = console.warn;

    function addLog(level, message) {
      recentLogs.value.unshift({
        level: level,
        message: message,
        timestamp: new Date().toLocaleTimeString(),
      });

      // Keep only last 10 logs
      if (recentLogs.value.length > 10) {
        recentLogs.value.pop();
      }
    }

    // Manual testing functions
    async function testWebSocketConnection() {
      testing.value = true;
      addLog('info', 'Testing WebSocket connection...');

      try {
        await websocketStore.connect();
        addLog('success', 'WebSocket connection test successful');
      } catch (error) {
        addLog('error', `WebSocket connection test failed: ${error.message}`);
      } finally {
        testing.value = false;
      }
    }

    async function requestDashboardData() {
      requesting.value = true;
      addLog('info', 'Requesting dashboard data via WebSocket...');

      try {
        // First test subscription
        addLog('info', 'Testing channel subscriptions...');
        websocketStore.subscribeToChannel('dashboard,dashboard_update');

        // Wait a moment for subscription to process
        await new Promise((resolve) => setTimeout(resolve, 1000));

        // Then request data
        addLog('info', 'Sending dashboard data request...');
        const result = await websocketStore.sendMessageByType('dashboard', {});
        addLog(
          'success',
          `Dashboard data received: ${result?.documents?.length || 0} documents`,
        );
        addLog(
          'info',
          `Response data keys: ${result ? Object.keys(result).join(', ') : 'none'}`,
        );

        if (result?.exception) {
          addLog('error', `Server exception: ${result.exception}`);
        }
        if (result?.message) {
          addLog('info', `Server message: ${result.message}`);
        }

        lastDataUpdate.value = new Date().toLocaleTimeString();
      } catch (error) {
        addLog('error', `Dashboard data request failed: ${error.message}`);
      } finally {
        requesting.value = false;
      }
    }

    function exportDiagnostics() {
      const diagnostics = {
        connectionStatus: connectionStatus.value,
        authStatus: authStatus.value,
        dataSource: dataSource.value,
        documentsCount: documentsCount.value,
        lastDataUpdate: lastDataUpdate.value,
        recentLogs: recentLogs.value,
        websocketState: {
          isConnected: isConnected.value,
          hasError: hasError.value,
          dashboard_data_flag: dashboard_data_flag.value,
        },
        timestamp: new Date().toISOString(),
      };

      const blob = new Blob([JSON.stringify(diagnostics, null, 2)], {
        type: 'application/json',
      });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = `websocket-diagnostics-${Date.now()}.json`;
      link.click();
      URL.revokeObjectURL(url);

      addLog('info', 'Diagnostics exported to file');
    }

    function clearLogs() {
      recentLogs.value = [];
      addLog('info', 'Logs cleared');
    }

    // Override console methods to capture WebSocket logs
    onMounted(() => {
      console.log = function (...args) {
        const message = args.join(' ');
        if (
          message.includes('[WebSocket]') ||
          message.includes('[Dashboard]')
        ) {
          addLog('info', message);
        }
        originalLog.apply(console, args);
      };

      console.error = function (...args) {
        const message = args.join(' ');
        if (
          message.includes('[WebSocket]') ||
          message.includes('[Dashboard]')
        ) {
          addLog('error', message);
        }
        originalError.apply(console, args);
      };

      console.warn = function (...args) {
        const message = args.join(' ');
        if (
          message.includes('[WebSocket]') ||
          message.includes('[Dashboard]')
        ) {
          addLog('warning', message);
        }
        originalWarn.apply(console, args);
      };

      addLog('info', 'WebSocket diagnostics initialized');
    });

    onUnmounted(() => {
      // Restore original console methods
      console.log = originalLog;
      console.error = originalError;
      console.warn = originalWarn;
    });

    return {
      connectionStatus,
      authStatus,
      tokenLength,
      dataSource,
      documentsCount,
      dashboard_data_flag,
      lastDataUpdate,
      recentLogs,
      testing,
      requesting,
      testWebSocketConnection,
      requestDashboardData,
      exportDiagnostics,
      clearLogs,
    };
  },
});
</script>

